"""Exact rational orbit computation on a Mordell curve y^2 = x^3 + N."""

from __future__ import annotations

from fractions import Fraction
from typing import List, Optional, Tuple

Point = Optional[Tuple[Fraction, Fraction]]


def add(P: Point, Q: Point) -> Point:
    """Chord-and-tangent addition on y^2 = x^3 + N (N enters only through the points)."""
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and y1 == -y2:
        return None
    if P == Q:
        if y1 == 0:
            return None
        lam = (3 * x1 * x1) / (2 * y1)
    else:
        lam = (y2 - y1) / (x2 - x1)
    x3 = lam * lam - x1 - x2
    return (x3, lam * (x1 - x3) - y1)


def exact_orbit(N: int, P: Tuple[int, int], n: int) -> List[Point]:
    """Return [P, 2P, ..., nP] with exact rational coordinates.

    Raises ValueError if P does not lie on y^2 = x^3 + N.
    """
    x0, y0 = Fraction(P[0]), Fraction(P[1])
    if y0 * y0 != x0 * x0 * x0 + N:
        raise ValueError(f"({P[0]}, {P[1]}) is not a point of y^2 = x^3 + {N}")
    base: Point = (x0, y0)
    out: List[Point] = []
    Q: Point = base
    for _ in range(n):
        out.append(Q)
        if Q is None:
            break
        Q = add(Q, base)
    return out


def denominator_profile(N: int, P: Tuple[int, int], n: int) -> List[Tuple[int, int, int]]:
    """Return (index, den x, e) with den x = e^2, verifying the square-denominator law."""
    rows: List[Tuple[int, int, int]] = []
    for k, Q in enumerate(exact_orbit(N, P, n), start=1):
        if Q is None:
            continue
        d = Q[0].denominator
        e = round(d ** 0.5)
        while e * e < d:
            e += 1
        if e * e != d:
            raise AssertionError("square-denominator law violated")
        if Q[1].denominator != e ** 3:
            raise AssertionError("den y = e^3 violated")
        rows.append((k, d, e))
    return rows


if __name__ == "__main__":
    for k, d, e in denominator_profile(55, (9, 28), 5):
        print(f"n = {k}:  den x = {d} = {e}^2")

"""Apparition index of a prime, computed in the finite group E_N(F_ell)."""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

FinitePoint = Optional[Tuple[int, int]]


def add_mod(P: FinitePoint, Q: FinitePoint, N: int, ell: int) -> FinitePoint:
    """Group law of y^2 = x^3 + N over the field with ell elements (ell >= 5)."""
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and (y1 + y2) % ell == 0:
        return None
    if P == Q:
        lam = 3 * x1 * x1 % ell * pow(2 * y1 % ell, ell - 2, ell) % ell
    else:
        lam = (y2 - y1) % ell * pow((x2 - x1) % ell, ell - 2, ell) % ell
    x3 = (lam * lam - x1 - x2) % ell
    return (x3, (lam * (x1 - x3) - y1) % ell)


def curve_order(N: int, ell: int) -> int:
    """#E_N(F_ell) by summing Legendre symbols: 1 + sum_x (1 + chi(x^3 + N))."""
    total = 1
    squares: Dict[int, int] = {}
    for t in range(ell):
        squares[t * t % ell] = squares.get(t * t % ell, 0) + 1
    for x in range(ell):
        total += squares.get((x * x % ell * x + N) % ell, 0)
    return total


def point_order(N: int, P: Tuple[int, int], ell: int) -> int:
    """Order of the reduction of P in E_N(F_ell); this is the apparition index of ell."""
    R: FinitePoint = (P[0] % ell, P[1] % ell)
    if (R[1] * R[1] - R[0] ** 3 - N) % ell != 0:
        raise ValueError("point is not on the reduced curve")
    S: FinitePoint = R
    k = 1
    bound = curve_order(N, ell) + 1
    while S is not None:
        S = add_mod(S, R, N, ell)
        k += 1
        if k > bound:
            raise RuntimeError("order exceeded the group order: bad input")
    return k


def apparition_indices(N: int, P: Tuple[int, int], primes: List[int]) -> Dict[int, int]:
    """Apparition index m(ell) for each good prime ell in the list."""
    out: Dict[int, int] = {}
    bad = {2, 3}
    n = abs(N)
    d = 2
    while d * d <= n:
        while n % d == 0:
            bad.add(d)
            n //= d
        d += 1
    if n > 1:
        bad.add(n)
    for ell in primes:
        if ell in bad or ell < 5:
            continue
        out[ell] = point_order(N, P, ell)
    return out


if __name__ == "__main__":
    idx = apparition_indices(55, (9, 28), [7, 13, 17, 19, 23, 29, 31, 37, 41, 43, 73])
    for ell in sorted(idx):
        print(f"m({ell:>3}) = {idx[ell]:>3}   "
              f"(#E_55(F_{ell}) = {curve_order(55, ell)})")

"""Denominator-valuation profiling: a falsifiable fingerprint for each structural law."""

from __future__ import annotations

from fractions import Fraction
from typing import Dict, List, Optional, Tuple

Point = Optional[Tuple[Fraction, Fraction]]


def add(P: Point, Q: Point) -> Point:
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and y1 == -y2:
        return None
    if P == Q:
        if y1 == 0:
            return None
        lam = (3 * x1 * x1) / (2 * y1)
    else:
        lam = (y2 - y1) / (x2 - x1)
    x3 = lam * lam - x1 - x2
    return (x3, lam * (x1 - x3) - y1)


def valuation(n: int, ell: int) -> int:
    v, n = 0, abs(n)
    while n % ell == 0:
        n //= ell
        v += 1
    return v


def valuation_table(N: int, P: Tuple[int, int], primes: List[int],
                    n_max: int) -> Dict[int, Dict[int, int]]:
    """table[k][ell] = v_ell(den x(kP)) for 1 <= k <= n_max."""
    base: Point = (Fraction(P[0]), Fraction(P[1]))
    table: Dict[int, Dict[int, int]] = {}
    Q: Point = base
    for k in range(1, n_max + 1):
        if Q is None:
            break
        d = Q[0].denominator
        table[k] = {ell: valuation(d, ell) for ell in primes}
        Q = add(Q, base)
    return table


def check_laws(N: int, P: Tuple[int, int], primes: List[int],
               n_max: int = 8) -> Dict[str, bool]:
    """Check the square law, the parity law, and periodicity of each appearance set."""
    table = valuation_table(N, P, primes, n_max)
    results: Dict[str, bool] = {}

    results["all valuations even (square-denominator law)"] = all(
        v % 2 == 0 for row in table.values() for v in row.values())

    periodic = True
    for ell in primes:
        support = [k for k in table if table[k][ell] > 0]
        if not support:
            continue
        m = min(support)
        if any((k % m == 0) != (table[k][ell] > 0) for k in table):
            periodic = False
    results["appearance sets are arithmetic progressions (index law)"] = periodic

    two_adic = True
    k, prev = 1, None
    while k <= n_max:
        if k in table and table[k].get(2, 0) > 0:
            if prev is not None and table[k][2] != prev + 2:
                two_adic = False
            prev = table[k][2]
        k *= 2
    results["v_2 grows by exactly 2 per doubling"] = two_adic
    return results


if __name__ == "__main__":
    primes = [2, 3, 5, 7, 13, 17, 73]
    table = valuation_table(55, (9, 28), primes, 7)
    print("   n |" + "".join(f"{p:>5}" for p in primes))
    for k in sorted(table):
        print(f"  {k:>2} |" + "".join(f"{table[k][p]:>5}" for p in primes))
    print()
    for law, ok in check_laws(55, (9, 28), primes).items():
        print(f"  {'PASS' if ok else 'FAIL'}  {law}")
